// gta6-meme-x-01 — "The countdown moved again."
//
// A GTA VI launch-week meme, painted by this program with Node 22 stdlib
// only (node:zlib, node:fs, node:crypto). No network, no dependencies.
//
// The artwork is embedded as data:
//   SCENE — the Vice City street backdrop, raw RGBA 1024x1024, zlib-packed.
//   MARK  — make.fun's real ghost mark (from the official press kit),
//           raw RGBA 160x160, zlib-packed.
// The program composites them with a 5x7 bitmap font: the wanted-level
// row (five gold stars + the ghost as the sixth star), a billboard with
// the moving GTA VI countdown, and a bottom bar pitching make.fun.
// It then PNG-encodes the result (CRC32 + deflate, filter 0) and writes
// meme.png. The output is byte-deterministic: same input, same PNG.
//
// Run:  node main.ts            (writes meme.png to MAKEFUN_OUTPUT_DIR,
//                                or /output when unset)

import { deflateSync, inflateSync } from "node:zlib";
import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";

const W = 1024;
const H = 1024;
const MARK_SRC = 160;

// ---------------------------------------------------------------- assets
const SCENE_B64 = "";
const MARK_B64 = "";

function unpack(b64: string): Buffer {
  return inflateSync(Buffer.from(b64, "base64"));
}

const scene: Buffer = unpack(SCENE_B64); // W*H*4 RGBA
const mark: Buffer = unpack(MARK_B64); // MARK_SRC*MARK_SRC*4 RGBA

// ---------------------------------------------------------------- canvas
// RGBA canvas, source-over compositing.
const px = Buffer.from(scene);

function blend(x: number, y: number, r: number, g: number, b: number, a: number): void {
  if (x < 0 || y < 0 || x >= W || y >= H || a <= 0) return;
  const i = (y * W + x) * 4;
  const sa = a / 255;
  const da = px[i + 3] / 255;
  const out = sa + da * (1 - sa);
  if (out <= 0) return;
  px[i] = Math.round((r * sa + px[i] * da * (1 - sa)) / out);
  px[i + 1] = Math.round((g * sa + px[i + 1] * da * (1 - sa)) / out);
  px[i + 2] = Math.round((b * sa + px[i + 2] * da * (1 - sa)) / out);
  px[i + 3] = Math.round(out * 255);
}

function fillRect(x: number, y: number, w: number, h: number, c: number[]): void {
  for (let yy = Math.max(0, y); yy < Math.min(H, y + h); yy++) {
    for (let xx = Math.max(0, x); xx < Math.min(W, x + w); xx++) {
      blend(xx, yy, c[0], c[1], c[2], c[3] ?? 255);
    }
  }
}

function fillCircle(cx: number, cy: number, r: number, c: number[]): void {
  for (let yy = Math.floor(cy - r); yy <= Math.ceil(cy + r); yy++) {
    for (let xx = Math.floor(cx - r); xx <= Math.ceil(cx + r); xx++) {
      const dx = xx - cx, dy = yy - cy;
      if (dx * dx + dy * dy <= r * r) blend(xx, yy, c[0], c[1], c[2], c[3] ?? 255);
    }
  }
}

function fillRoundRect(x: number, y: number, w: number, h: number, r: number, c: number[]): void {
  fillRect(x + r, y, w - 2 * r, h, c);
  fillRect(x, y + r, w, h - 2 * r, c);
  fillCircle(x + r, y + r, r, c);
  fillCircle(x + w - r, y + r, r, c);
  fillCircle(x + r, y + h - r, r, c);
  fillCircle(x + w - r, y + h - r, r, c);
}

// Scanline polygon fill (even-odd).
function fillPolygon(pts: number[][], c: number[]): void {
  let minY = H, maxY = 0;
  for (const p of pts) { minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]); }
  for (let y = Math.max(0, Math.floor(minY)); y <= Math.min(H - 1, Math.ceil(maxY)); y++) {
    const xs: number[] = [];
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i], b = pts[(i + 1) % pts.length];
      if ((a[1] <= y && b[1] > y) || (b[1] <= y && a[1] > y)) {
        xs.push(a[0] + ((y - a[1]) * (b[0] - a[0])) / (b[1] - a[1]));
      }
    }
    xs.sort((p, q) => p - q);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      for (let x = Math.max(0, Math.ceil(xs[k])); x <= Math.min(W - 1, Math.floor(xs[k + 1])); x++) {
        blend(x, y, c[0], c[1], c[2], c[3] ?? 255);
      }
    }
  }
}

function fillStar(cx: number, cy: number, rO: number, rI: number, c: number[]): void {
  const pts: number[][] = [];
  for (let i = 0; i < 10; i++) {
    const r = i % 2 === 0 ? rO : rI;
    const ang = -Math.PI / 2 + (i * Math.PI) / 5;
    pts.push([cx + r * Math.cos(ang), cy + r * Math.sin(ang)]);
  }
  fillPolygon(pts, c);
}

// Thick line (for the strike-through) as stamped circles.
function thickLine(x0: number, y0: number, x1: number, y1: number, w: number, c: number[]): void {
  const len = Math.hypot(x1 - x0, y1 - y0);
  const steps = Math.ceil(len);
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    fillCircle(x0 + (x1 - x0) * t, y0 + (y1 - y0) * t, w / 2, c);
  }
}

// Blit the ghost mark, box-average downscaled to `size` px.
function blitMark(dx: number, dy: number, size: number): void {
  const scale = MARK_SRC / size;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const sx0 = Math.floor(x * scale), sy0 = Math.floor(y * scale);
      const sx1 = Math.min(MARK_SRC, Math.ceil((x + 1) * scale));
      const sy1 = Math.min(MARK_SRC, Math.ceil((y + 1) * scale));
      let r = 0, g = 0, b = 0, a = 0, n = 0;
      for (let sy = sy0; sy < sy1; sy++) {
        for (let sx = sx0; sx < sx1; sx++) {
          const j = (sy * MARK_SRC + sx) * 4;
          r += mark[j]; g += mark[j + 1]; b += mark[j + 2]; a += mark[j + 3]; n++;
        }
      }
      if (n > 0 && a > 0) blend(dx + x, dy + y, r / n, g / n, b / n, a / n);
    }
  }
}

// ---------------------------------------------------------------- font
// 5x7 bitmap font. Each glyph is 7 rows of 5 bits (bit 4 = leftmost pixel).
const FONT: Record<string, number[]> = {
  A: [0b01110, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001],
  B: [0b11110, 0b10001, 0b10001, 0b11110, 0b10001, 0b10001, 0b11110],
  C: [0b01110, 0b10001, 0b10000, 0b10000, 0b10000, 0b10001, 0b01110],
  D: [0b11110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b11110],
  E: [0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b11111],
  G: [0b01110, 0b10001, 0b10000, 0b10111, 0b10001, 0b10001, 0b01111],
  H: [0b10001, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001],
  I: [0b01110, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b01110],
  K: [0b10001, 0b10010, 0b10100, 0b11000, 0b10100, 0b10010, 0b10001],
  L: [0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b11111],
  M: [0b10001, 0b11011, 0b10101, 0b10101, 0b10001, 0b10001, 0b10001],
  N: [0b10001, 0b11001, 0b10101, 0b10011, 0b10001, 0b10001, 0b10001],
  O: [0b01110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01110],
  P: [0b11110, 0b10001, 0b10001, 0b11110, 0b10000, 0b10000, 0b10000],
  S: [0b01111, 0b10000, 0b10000, 0b01110, 0b00001, 0b00001, 0b11110],
  T: [0b11111, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100],
  U: [0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01110],
  V: [0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01010, 0b00100],
  W: [0b10001, 0b10001, 0b10001, 0b10101, 0b10101, 0b11011, 0b10001],
  Y: [0b10001, 0b10001, 0b01010, 0b00100, 0b00100, 0b00100, 0b00100],
  "1": [0b00100, 0b01100, 0b00100, 0b00100, 0b00100, 0b00100, 0b01110],
  "2": [0b01110, 0b10001, 0b00001, 0b00110, 0b01000, 0b10000, 0b11111],
  "3": [0b11111, 0b00010, 0b00100, 0b00010, 0b00001, 0b10001, 0b01110],
  "7": [0b11111, 0b00001, 0b00010, 0b00100, 0b01000, 0b01000, 0b01000],
  a: [0b00000, 0b00000, 0b01110, 0b00001, 0b01111, 0b10001, 0b01111],
  e: [0b00000, 0b00000, 0b01110, 0b10001, 0b11111, 0b10000, 0b01110],
  f: [0b00110, 0b01000, 0b01000, 0b11110, 0b01000, 0b01000, 0b01000],
  k: [0b00000, 0b10000, 0b10010, 0b10100, 0b11000, 0b10100, 0b10010],
  m: [0b00000, 0b00000, 0b11010, 0b10101, 0b10101, 0b10101, 0b10101],
  n: [0b00000, 0b00000, 0b11110, 0b10001, 0b10001, 0b10001, 0b10001],
  u: [0b00000, 0b00000, 0b10001, 0b10001, 0b10001, 0b10011, 0b01101],
  ".": [0b00000, 0b00000, 0b00000, 0b00000, 0b00000, 0b01100, 0b01100],
  ",": [0b00000, 0b00000, 0b00000, 0b00000, 0b01100, 0b00100, 0b01000],
};

function textWidth(text: string, scale: number): number {
  return text.length * 6 * scale - scale;
}

function drawTextRaw(text: string, x: number, y: number, scale: number, c: number[]): void {
  let cx = x;
  for (const ch of text) {
    const glyph = FONT[ch];
    if (glyph) {
      for (let row = 0; row < 7; row++) {
        for (let col = 0; col < 5; col++) {
          if (glyph[row] & (1 << (4 - col))) {
            fillRect(cx + col * scale, y + row * scale, scale, scale, c);
          }
        }
      }
    }
    cx += 6 * scale;
  }
}

// Centered text with a dark outline so it stays readable over the scene.
function drawText(text: string, cx: number, y: number, scale: number, c: number[]): void {
  const x = Math.round(cx - textWidth(text, scale) / 2);
  const o = Math.max(1, Math.round(scale / 3));
  const outline = [16, 12, 24, 255];
  for (const [dx, dy] of [[-o, 0], [o, 0], [0, -o], [0, o], [-o, -o], [o, -o], [-o, o], [o, o]]) {
    drawTextRaw(text, x + dx, y + dy, scale, outline);
  }
  drawTextRaw(text, x, y, scale, c);
}

// ---------------------------------------------------------------- palette
const GOLD = [255, 205, 60, 255];
const GOLD_DK = [176, 120, 0, 255];
const WHITE = [255, 255, 255, 255];
const GREY = [150, 150, 160, 255];
const GREY_LT = [200, 200, 210, 255];
const PINK = [255, 136, 196, 255]; // make.fun magenta ink on dark
const MAGENTA = [196, 28, 131, 255]; // make.fun brand magenta
const RED = [230, 40, 60, 255];
const INK = [25, 20, 25, 255];
const PANEL = [16, 12, 24, 255];

// ---------------------------------------------------------------- compose
// 1. Wanted row: dark pill, "WANTED", five gold stars, ghost as 6th star.
fillRoundRect(252, 34, 520, 122, 28, [25, 16, 31, 255]);
drawText("WANTED", 512, 48, 4, GOLD);
for (let i = 0; i < 5; i++) {
  const cx = 322 + i * 76;
  fillStar(cx, 118, 30, 13, GOLD_DK);
  fillStar(cx, 118, 26, 11, GOLD);
}
blitMark(702 - 44, 118 - 44, 88);

// 2. Billboard on posts, with the moving countdown.
fillRect(300, 690, 24, 110, INK);
fillRect(700, 690, 24, 110, INK);
fillRect(162, 330, 700, 360, MAGENTA);
fillRect(168, 336, 688, 348, PANEL);
drawText("GTA VI", 512, 358, 9, WHITE);
drawText("172 DAYS", 512, 446, 7, GREY);
thickLine(340, 458, 684, 486, 9, RED);
drawText("173 DAYS", 512, 516, 9, PINK);
drawText("CHECKED AGAIN. IT MOVED.", 512, 612, 3, GREY_LT);

// 3. Bottom bar: pitch + ghost + wordmark.
fillRect(0, 852, 1024, 172, INK);
fillRect(0, 852, 1024, 6, MAGENTA);
drawText("WHILE YOU WAIT, GET PAID TO BUILD.", 512, 880, 4, WHITE);
blitMark(333, 936, 56);
drawText("make.fun", 403 + textWidth("make.fun", 6) / 2, 936, 6, WHITE);

// ---------------------------------------------------------------- PNG out
const CRC_TABLE: number[] = [];
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  CRC_TABLE[n] = c >>> 0;
}
function crc32(buf: Buffer): number {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function chunk(type: string, data: Buffer): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, "ascii");
  data.copy(out, 8);
  out.writeUInt32BE(crc32(Buffer.concat([Buffer.from(type, "ascii"), data])), 8 + data.length);
  return out;
}

const raw = Buffer.alloc(H * (1 + W * 4));
for (let y = 0; y < H; y++) {
  raw[y * (1 + W * 4)] = 0; // filter: none
  px.copy(raw, y * (1 + W * 4) + 1, y * W * 4, (y + 1) * W * 4);
}
const ihdr = Buffer.alloc(13);
ihdr.writeUInt32BE(W, 0);
ihdr.writeUInt32BE(H, 4);
ihdr[8] = 8; // bit depth
ihdr[9] = 6; // color type RGBA
ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
const png = Buffer.concat([
  Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
  chunk("IHDR", ihdr),
  chunk("IDAT", deflateSync(raw, { level: 9 })),
  chunk("IEND", Buffer.alloc(0)),
]);

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(`${outDir}/meme.png`, png);
console.log(`meme.png ${W}x${H} ${png.length} bytes sha256=${createHash("sha256").update(png).digest("hex")}`);
